@inject ITmNotificationService NotificationService

<TmNotificationBell CurrentUserId="user-1" />

<TmButton OnClick="PublishAsync">Publish</TmButton>

@code {
    private Task PublishAsync()
        => NotificationService.PublishAsync(new TmNotification
        {
            RecipientUserId = "user-1",
            Type = TmNotificationTypes.Mention,
            Title = "You were mentioned",
            Body = "Open the document to review the comment.",
            ActionUrl = "/documents/42"
        });
}
